public void tick(Level level) {
        if (this.previousPosition == null) {
            this.previousPosition = this.getAdjustedPosition();
        }
        Vec3 pos = getAdjustedPosition();

        Vec2 adjustedRotation = getAdjustedRotation();
        particleOptions.map.set(ParticlePropertyRegistry.EMITTER_PROPERTY.get(), new EmitterProperty(new Vec2(adjustedRotation.x, adjustedRotation.y), age));
        if (level instanceof ServerLevel serverLevel) {
            Networking.sendToNearbyClient(serverLevel, BlockPos.containing(pos), new TickEmitterPacket(this));
        } else {
            particleConfig.tick(particleOptions, level, pos.x, pos.y, pos.z, previousPosition.x, previousPosition.y, previousPosition.z);
        }
        this.previousPosition = pos;
        this.age++;
    }

@Override
    public void tick(PropertyParticleOptions particleOptions, Level level, double x, double y, double z, double prevX, double prevY, double prevZ) {
        ParticleDensityProperty densityProp = getDensity(particleOptions, 100, 0.1f);
        SpeedProperty speedProperty = getSpeed(particleOptions);
        double minXSpeed = speedProperty.minXZ() * 0.25f;
        double minYSpeed = speedProperty.minY() * 0.25f;
        double maxXSpeed = speedProperty.maxXZ() * 0.25f;
        double maxYSpeed = speedProperty.maxY() * 0.25f;

        int density = densityProp.density();
        double radius = densityProp.radius();
        SpawnType spawnType = densityProp.spawnType().orElse(SpawnType.SPHERE);

        int totalParticles = getNumParticles(density);
        double deltaX = x - prevX;
        double deltaY = y - prevY;
        double deltaZ = z - prevZ;
        for (int i = 0; i < totalParticles; i++) {
            double t = (double) i / Math.max(1, totalParticles - 1);
            double px = prevX + deltaX * t;
            double py = prevY + deltaY * t;
            double pz = prevZ + deltaZ * t;
            Vec3 deltaVec = new Vec3(px, py, pz);
            Vec3 point = getMotionScaled(deltaVec, radius, spawnType);
            level.addAlwaysVisibleParticle(
                    particleOptions,
                    true,
                    point.x,
                    point.y,
                    point.z,
                    ParticleUtil.inRange(minXSpeed, maxXSpeed),
                    ParticleUtil.inRange(minYSpeed, maxYSpeed),
                    ParticleUtil.inRange(minXSpeed, maxXSpeed));
        }
    }

@Override
    public void tick(PropertyParticleOptions particleOptions, Level level, double x, double y, double z, double prevX, double prevY, double prevZ) {
        int age = emitter.age;
        if (age == 0)
            return;
        ParticleDensityProperty density = getDensity(particleOptions, 100, 0.3f);
        int totalParticles = getNumParticles(density.density());
        float randomScale = 0.00f;
        double radius = density.radius();
        for (int step = 0; step <= totalParticles; step++) {
            double t = (double) step / totalParticles;
            double interpolatedX = prevX + t * (x - prevX);
            double interpolatedY = prevY + t * (y - prevY);
            double interpolatedZ = prevZ + t * (z - prevZ);
            double motionProgress = age + t;
            Vec3 local = getZigzag3D(motionProgress, 8, radius, 12, radius - radius * 0.3, 0.1);
            Vector3f transformed = toEmitterSpace((float) interpolatedX, (float) interpolatedY, (float) interpolatedZ,
                    (float) local.x(), (float) local.y(), (float) local.z);

            level.addParticle(particleOptions, transformed.x, transformed.y, transformed.z,
                    ParticleUtil.inRange(-randomScale, randomScale),
                    ParticleUtil.inRange(-randomScale, randomScale),
                    ParticleUtil.inRange(-randomScale, randomScale));
        }
    }

public void playParticles() {
        if (tickEmitter == null && resolver() != null) {
            buildEmitters();
        }
        if (this.tickEmitter != null) {
            this.tickEmitter.tick(level);
        }

        if (flairEmitter != null) {
            this.flairEmitter.tick(level);
        }

        if (!playedSpawnParticle && onSpawnEmitter != null) {
            this.onSpawnEmitter.tick(level);
            playedSpawnParticle = true;
        }
    }

@Override
    public void tick(PropertyParticleOptions particleOptions, Level level, double x, double y, double z, double prevX, double prevY, double prevZ) {
        WallProperty wallProperty = particleOptions.map.getOrDefault(ParticlePropertyRegistry.WALL_PROPERTY.get(), new WallProperty(5, 5, 20, Direction.NORTH));
        ParticleDensityProperty density = getDensity(particleOptions, 20, 0.0f);
        RandomSource rand = level.random;
        int chance = wallProperty.chance;
        int range = wallProperty.range;
        double growthFactor = 1.0f;
        Direction direction = wallProperty.direction;

        BlockPos pos = BlockPos.containing(x, y, z);

        BlockPos.betweenClosedStream(pos.offset(range * direction.getStepX(), 0, range * direction.getStepZ()), pos.offset(-range * direction.getStepX(), range, -range * direction.getStepZ())).forEach(blockPos -> {
            if (rand.nextInt(chance) == 0) {
                for (int i = 0; i < getNumParticles(density.density()); i++) {
                    double dx = blockPos.getX() + ParticleUtil.inRange(-growthFactor, growthFactor) + 0.5;
                    double dy = blockPos.getY() + ParticleUtil.inRange(-growthFactor, growthFactor) + 0.5;
                    double dz = blockPos.getZ() + ParticleUtil.inRange(-growthFactor, growthFactor) + 0.5;
                    level.addAlwaysVisibleParticle(particleOptions,
                            true,
                            dx, dy, dz,
                            0, ParticleUtil.inRange(0.01, 0.08), 0);
                }
            }
        });
    }

public void castSpells() {
        float aoe = getAoe();
        int flatAoe = Math.round(aoe);
        BlockPos start = blockPosition().offset(flatAoe * getDirection().getStepX(), 0, flatAoe * getDirection().getStepZ());
        BlockPos end = blockPosition().offset(-flatAoe * getDirection().getStepX(), flatAoe, -flatAoe * getDirection().getStepZ());
        if (isSensitive()) {
            if (age % (Math.max(1, 20 - 2 * getAccelerates())) != 0 && age != 1)
                return;
            for (BlockPos p : BlockPos.betweenClosed(start, end)) {
                p = p.immutable();
                if (!level.isClientSide) {
                    resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new
                            BlockHitResult(new Vec3(p.getX(), p.getY(), p.getZ()), Direction.UP, p, false));
                }
                resolveEmitter.setPositionOffset(p.subtract(blockPosition()).getCenter());
                if (level.isClientSide) {
                    resolveEmitter.tick(level);
                }
            }
            if (!level.isClientSide) {
                resolveSound.playSound(level, getX(), getY(), getZ());
            }
        } else {
            int i = 0;
            // Expand the axis if start and end are equal

            AABB aabb = AABB.encapsulatingFullBlocks(start, end);
            if (aabb.maxX == aabb.minX) {
                aabb = aabb.inflate(growthFactor, 0, 0);
            }
            if (aabb.maxY == aabb.minY) {
                aabb = aabb.inflate(0, growthFactor, 0);
            }
            if (aabb.maxZ == aabb.minZ) {
                aabb = aabb.inflate(0, 0, growthFactor);
            }
            for (Entity entity : level.getEntities(null, aabb)) {
                if (entity.equals(this) || entity.getType().is(EntityTags.LINGERING_BLACKLIST)) {
                    continue;
                }
                Optional<EntityHit> hit = hitEntities.stream().filter(e -> e.entity.refersTo(entity)).findFirst();
                boolean skipEntity = hit.isPresent();
                if (hit.isPresent() && level.getGameTime() - hit.get().gameTime > 20) {
                    hitEntities.remove(hit.get());
                    skipEntity = false;
                }
                if (skipEntity)
                    continue;
                if (!level.isClientSide) {
                    resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new EntityHitResult(entity));
                }
                resolveEmitter.setPositionOffset(entity.position.subtract(position).add(0, entity.getBbHeight() / 2.0, 0));
                if (level.isClientSide) {
                    resolveEmitter.tick(level);
                }
                i++;
                if (hit.isEmpty()) {
                    hitEntities.add(new EntityHit(entity));
                }
                if (i > 5)
                    break;
                if (!level.isClientSide) {
                    resolveSound.playSound(level, getX(), getY(), getZ());
                }
            }
            totalProcs += i;
            if (totalProcs >= maxProcs)
                this.remove(RemovalReason.DISCARDED);
        }
    }
